        greet("Mia", 3);
    }

    static void printBar(String name, int length) {
        System.out.print(name + " | ");
        for (int i = 1; i <= length; i++) {
            System.out.print("#");
        }
        System.out.println();
    }

    static void greet(String name, int times) {
        for (int i = 1; i <= times; i++) {
            System.out.println("Hello, " + name + "!");
        }
    }
}

