import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Name? ");
        String name = scanner.nextLine();

        System.out.print("Score out of 100? ");
        int score = scanner.nextInt();

        printBar(name, score / 10);
        describe(score);
    }

    static void printBar(String label, int length) {
        System.out.print(label + " | ");
        for (int i = 1; i <= length; i++) {
            System.out.print("#");
        }
        System.out.println();
    }

    static void describe(int score) {
        if (score >= 75) {
            System.out.println("Excellent.");
        } else if (score >= 40) {
            System.out.println("A pass.");
        } else {
            System.out.println("Needs work.");
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        askAndDouble(scanner, "First number");
        askAndDouble(scanner, "Second number");
    }

    static void askAndDouble(Scanner scanner, String label) {
        System.out.print(label + "? ");
        int n = scanner.nextInt();
        System.out.println(label + " doubled is " + n * 2);
    }
}

